def sum_of_largest_divisors(n):
    divisors = []
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            divisors.append(i)
            if i != n // i:
                divisors.append(n // i)
    divisors.sort()
    if len(divisors) < 2:
        return 0
    return divisors[-1] + divisors[-2]

count = 0
num = 10000012
while count < 5:
    if num % 1000 == 112 and sum_of_largest_divisors(num) < 100000:
        print(f"{num} {sum_of_largest_divisors(num)}")
        count += 1
    num += 1000
```

Ответ: 10011112 671 10111112 487 1021111

