from sympy import isprime, divisors, primefactors

def count_divisors(n):
    return len(divisors(n))

def is_valid_number(n):
    factors = primefactors(n)
    if len(factors) != 9:
        return False
    if count_divisors(n) % 90 != 0:
        return False
    return True

def find_numbers():
    numbers = []
    max_prime_factors = []
    num = 5200001
    while len(numbers) < 5:
        if is_valid_number(num):
            numbers.append(num)
            max_prime_factors.append(max(primefactors(num)))
        num += 1
    return numbers, max_prime_factors

numbers, max_prime_factors = find_numbers()
for i in range(5):
    print(f"{numbers[i]}\t{max_prime_factors[i]}")
```

Ответ: 5200320 7; 52

